# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ANLAM ARAYIŞI TEMASI: HİKÂYE (KURMACA) VE ANI (GERÇEK) KARŞILAŞTIRMASI</text>\n  <rect x="20" y="45" width="210" height="180" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">HİKÂYE (ÖYKÜ) TÜRÜ</text>\n  <text x="32" y="92" font-size="10.5" fill="#7f1d1d">• Metin Grubu: Edebî (Sanatsal)</text>\n  <text x="32" y="114" font-size="10.5" font-weight="bold" fill="#991b1b">• Gerçeklik: Kurmaca gerçeklik</text>\n  <text x="32" y="136" font-size="10.5" fill="#7f1d1d">• Anlatıcı: Kurmaca kişi (kahraman,</text>\n  <text x="32" y="154" font-size="10.5" fill="#7f1d1d">  gözlemci veya hâkim bakış)</text>\n  <text x="32" y="176" font-size="10.5" fill="#7f1d1d">• Dil: İmgesel, mecazlı, yan ve</text>\n  <text x="32" y="194" font-size="10.5" font-weight="bold" fill="#991b1b">  çağrışımsal anlam ağırlıklı</text>\n\n  <rect x="245" y="45" width="210" height="180" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ANI (HATIRA) TÜRÜ</text>\n  <text x="257" y="92" font-size="10.5" fill="#1e3a8a">• Metin Grubu: Kişisel hayatı</text>\n  <text x="257" y="110" font-size="10.5" fill="#1e3a8a">  konu alan öğretici metin</text>\n  <text x="257" y="132" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Gerçeklik: Yaşanmış gerçeklik</text>\n  <text x="257" y="154" font-size="10.5" fill="#1e3a8a">• Anlatıcı: Yazarın bizzat kendisi</text>\n  <text x="257" y="176" font-size="10.5" fill="#1e3a8a">• Zaman: Geçmişte yaşanan olayın</text>\n  <text x="257" y="194" font-size="10.5" font-weight="bold" fill="#1d4ed8">  zaman geçtikten sonra yazılması</text>\n\n  <rect x="470" y="45" width="210" height="180" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">ORTAK YÖN &amp; YARGILAR</text>\n  <text x="482" y="92" font-size="10.5" fill="#14532d">• Öyküleyici ve betimleyici</text>\n  <text x="482" y="110" font-size="10.5" fill="#14532d">  anlatım biçimlerini kullanma</text>\n  <text x="482" y="134" font-size="10.5" font-weight="bold" fill="#15803d">• Nesnel Yargı: Kanıtlanabilir,</text>\n  <text x="482" y="152" font-size="10.5" fill="#14532d">  kişisel yorum içermeyen bilgi</text>\n  <text x="482" y="176" font-size="10.5" font-weight="bold" fill="#15803d">• Öznel Yargı: Duygu, beğeni ve</text>\n  <text x="482" y="194" font-size="10.5" fill="#14532d">  kişisel izlenim içeren ifade</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SÖZ VARLIĞI VE DİL BİLGİSİ: TAMLAMALAR İLE EDAT - BAĞLAÇ - ÜNLEM</text>\n  <rect x="20" y="45" width="320" height="180" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">İSİM VE SIFAT TAMLAMALARI</text>\n  <text x="34" y="92" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Belirtili İsim Tamlaması (Tamlayan -ın + Tamlanan -ı):</text>\n  <text x="42" y="108" font-size="10.5" fill="#1e3a8a">\'konağın kapısı\', \'yazarın üslubu\'</text>\n  <text x="34" y="128" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Belirtisiz İsim Tamlaması (Tamlayan Ø + Tamlanan -ı):</text>\n  <text x="42" y="144" font-size="10.5" fill="#1e3a8a">\'konak kapısı\', \'anı defteri\'</text>\n  <text x="34" y="164" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Zincirleme İsim Tamlaması (En az 3 isim):</text>\n  <text x="42" y="180" font-size="10.5" fill="#1e3a8a">\'kasaba meydanının çınarı\', \'bahçe kapısının kilidi\'</text>\n  <text x="34" y="202" font-size="10.5" font-weight="bold" fill="#1e40af">• Sıfat Tamlaması (Sıfat + İsim): \'yorgun yolcu, bu ses\'</text>\n\n  <rect x="360" y="45" width="320" height="180" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">EDAT (İLGEÇ), BAĞLAÇ VE ÜNLEM</text>\n  <text x="374" y="92" font-size="10.5" font-weight="bold" fill="#b45309">• Edat (İlgeç): Sözcükler arası anlam ilgisi kurar</text>\n  <text x="382" y="108" font-size="10.5" fill="#78350f">\'gibi, için, göre, kadar, doğru, karşı, rağmen, ile\'</text>\n  <text x="374" y="132" font-size="10.5" font-weight="bold" fill="#b45309">• Bağlaç: Eş görevli unsurları veya cümleleri bağlar</text>\n  <text x="382" y="148" font-size="10.5" fill="#78350f">\'ve, veya, ama, fakat, lakin, çünkü, de, ki, hâlbuki\'</text>\n  <text x="374" y="172" font-size="10.5" font-weight="bold" fill="#b45309">• Ünlem: Coşkulu duygu veya seslenme bildirir</text>\n  <text x="382" y="188" font-size="10.5" fill="#78350f">\'ey, ah, vah, eyvah, hey, aman!\'</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">EDEBİYAT ATÖLYESİ (KONUŞMA): KARAKTER ÖZDEŞLEŞTİRME SUNUMU</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">1. HAZIRLIK VE ÖZDEŞLEŞTİRME</text>\n  <text x="32" y="92" font-size="10.5" fill="#581c87">• Hikâyedeki karakterin fiziksel ve</text>\n  <text x="32" y="110" font-size="10.5" fill="#581c87">  ruhsal özelliklerini belirleme</text>\n  <text x="32" y="134" font-size="10.5" font-weight="bold" fill="#7e22ce">• Günlük hayattan bir kişiyle</text>\n  <text x="32" y="152" font-size="10.5" font-weight="bold" fill="#7e22ce">  benzer yönlerini eşleştirme</text>\n  <text x="32" y="176" font-size="10.5" fill="#581c87">• Karakter (çok yönlü birey) ile</text>\n  <text x="32" y="194" font-size="10.5" fill="#581c87">  Tip (tek boyutlu temsil) ayrımı</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">2. İÇERİK VE YAPI PLANI</text>\n  <text x="257" y="92" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Giriş: Hitap, merak uyandırma</text>\n  <text x="257" y="110" font-size="10.5" fill="#1e3a8a">  ve seçilen karakteri tanıtma</text>\n  <text x="257" y="134" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Gelişme: Metinden alıntılar ve</text>\n  <text x="257" y="152" font-size="10.5" fill="#1e3a8a">  gerçek yaşamdan somut örnekler</text>\n  <text x="257" y="176" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Sonuç: İnsani mesaj ve değer</text>\n  <text x="257" y="194" font-size="10.5" fill="#1e3a8a">  vurgusuyla konuşmayı bitirme</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">3. SUNUM VE BEDEN DİLİ</text>\n  <text x="482" y="92" font-size="10.5" fill="#14532d">• Doğru telaffuz (boğumlama),</text>\n  <text x="482" y="110" font-size="10.5" fill="#14532d">  vurgu ve işitilebilir ses tonu</text>\n  <text x="482" y="134" font-size="10.5" font-weight="bold" fill="#15803d">• Dinleyicilerle göz teması kurma</text>\n  <text x="482" y="154" font-size="10.5" fill="#14532d">• Doğal jest ve mimik kullanımı</text>\n  <text x="482" y="176" font-size="10.5" fill="#14532d">• Görsel-işitsel materyal ve</text>\n  <text x="482" y="194" font-size="10.5" fill="#14532d">  süre yönetimi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
